import itertools
import random

def is_representable(T, S, max_k=10):
    n = len(T)
    s = len(S)
    valid_K = []
    for K in itertools.product(range(max_k + 1), repeat=s):
        is_valid = True
        for m in range(n):
            val = sum(K[i] * S[i][m] for i in range(s))
            if val > T[m]:
                is_valid = False
                break
        if is_valid:
            valid_K.append(K)
    if not valid_K:
        return False
    for m in range(n):
        found = False
        for K in valid_K:
            if sum(K[i] * S[i][m] for i in range(s)) == T[m]:
                found = True
                break
        if not found:
            return False
    return True

